export default function Dorsal({ atleta }: { atleta: any }) {
  // Formatea el ID a 2 o 3 dígitos según el tamaño del número
  const displayId = typeof atleta.id === 'number' 
    ? atleta.id.toString().padStart(2, '0') 
    : atleta.id.toString().substring(0, 4).toUpperCase();

  const miImagenBase64 = "data:image/png;base64,";

  return (
    <div 
      className="w-full relative overflow-hidden font-serif bg-white shadow-lg mx-auto" 
      style={{ aspectRatio: '1 / 1', containerType: 'inline-size', maxWidth: '1080px' }}
    >
      {/* IMAGEN DE FONDO (Plantilla Oficial) */}
      <img 
        src={miImagenBase64} 
        alt="Plantilla Dorsal" 
        className="absolute inset-0 w-full h-full object-cover z-0"
      />
      
      {/* NÚMERO GIGANTE CENTRAL */}
      {/* Usamos flex y centrado exacto en el bloque libre de la imagen (arriba del sol) */}
      <div className="absolute top-[32%] left-0 w-full h-[30%] flex justify-center items-center z-10">
        <span 
          className="font-black leading-none text-[#2A1E17]" 
          style={{ fontSize: '28cqw', letterSpacing: '-0.02em' }}
        >
          {displayId}
        </span>
      </div>

      {/* ================= DATOS DEL CORREDOR ================= */}
      
      {/* NOMBRE VALOR */}
      <div className="absolute top-[78%] left-[6.5%] w-[55%] z-10">
        <p className="text-white font-bold uppercase truncate" style={{ fontSize: '3.8cqw' }}>
          {atleta.nombre}
        </p>
      </div>

      {/* CATEGORÍA VALOR */}
      <div className="absolute top-[90.5%] left-[6.5%] w-[55%] z-10">
        <p className="text-white font-bold uppercase truncate" style={{ fontSize: '3.8cqw' }}>
          {atleta.categoria}
        </p>
      </div>

      {/* SEXO (Letras F y M centradas matemáticamente dentro de los recuadros) */}
      {/* Recuadro F */}
      <div className="absolute top-[79.3%] left-[69.5%] w-[8.5%] h-[6%] flex justify-center items-center z-10">
        <p className="text-white font-black" style={{ fontSize: '4cqw' }}>F</p>
      </div>
      {/* Recuadro M */}
      <div className="absolute top-[79.3%] left-[82.5%] w-[8.5%] h-[6%] flex justify-center items-center z-10">
        <p className="text-white font-black" style={{ fontSize: '4cqw' }}>M</p>
      </div>

      {/* EDAD VALOR */}
      <div className="absolute top-[90.5%] left-[69.5%] w-[25%] z-10 flex items-center">
        <p className="text-white font-bold uppercase" style={{ fontSize: '4cqw' }}>
          {atleta.edad}
        </p>
      </div>
    </div>
  );
}